{"version":1,"taskId":"9f009986-bf51-4022-aed0-124767c7b227","commandId":"merge-2","operation":"run","headSha":"525f35345ddc2f81e6b1dcffbfe1f88919bf6b5a","command":"set -e
git fetch origin cornel/cameracontroller-core-bd3382
git merge --no-edit FETCH_HEAD || true
cat > src/camera/index.ts <<'EOF'
export * from './CameraCollision';
